            {/* Favorites count */}
            {favorites.length > 0 && (
              <Button
                color="secondary"
                pill
                size="lg"
                uniform
                variant="ghost"
                className="text-danger/80"
              >
                <HeartFilled />
                {favorites.length}
              </Button>
            )}

            {/* Display mode buttons */}
            {!isFullscreen && !isPip && (
              <>
                <Button
                  color="secondary"
                  pill
                  size="lg"
                  uniform
                  variant="outline"
                  onClick={() => requestDisplayMode("pip")}
                  title="Picture-in-picture"
