                </Button>
                <Button
                  color="secondary"
                  pill
                  size="lg"
                  uniform
                  variant="outline"
                  onClick={() => requestDisplayMode("fullscreen")}
                  title="Fullscreen"
                >
                  <Expand />
                </Button>
              </>
            )}

            {(isFullscreen || isPip) && (
              <Button
                color="secondary"
                pill
                size="lg"
                uniform
                variant="outline"
                onClick={() => requestDisplayMode("inline")}
                title="Exit"
              >
                <svg
                  width="14"
                  height="14"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
