/**
 * Registers the product-search MCP App widget and its companion data tool.
 *
 * Widget UI:  resources/product-search-result/widget.tsx
 *             ↑ This is the React component rendered in the iframe.
 *
 * Tools registered here:
 *   - search-tools       → triggers the widget UI (visual search results carousel)
 *   - get-fruit-details  → data tool called from within the widget via useCallTool()
 */
export function register(server: MCPServer) {
  // MCP App widget tool — calls return widget({ props }) which renders the React component
  server.tool(
    {
      name: "search-tools",
      description:
        "Search for fruits and display the results in a visual widget",
      schema: z.object({
        query: z.string().optional().describe("Search query to filter fruits"),
      }),
      widget: {
        name: "product-search-result", // must match the folder name under resources/
        invoking: "Searching...",
        invoked: "Results loaded",
      },
      _meta: {
        // Preview data shown in MCP UI Studio when no live call has been made yet
        "ui/previewData": {
          query: "tropical",
          results: [
            { fruit: "mango", color: "bg-[#FBF1E1] dark:bg-[#FBF1E1]/10" },
            { fruit: "pineapple", color: "bg-[#f8f0d9] dark:bg-[#f8f0d9]/10" },
            { fruit: "coconut", color: "bg-[#fbedd3] dark:bg-[#fbedd3]/10" },
            { fruit: "banana", color: "bg-[#fdf0dd] dark:bg-[#fdf0dd]/10" },
          ],
        },
      },
    },
    async ({ query }) => {
      const results = fruits.filter(
        (f) => !query || f.fruit.toLowerCase().includes(query.toLowerCase()),
      );
      // Simulate network delay to demonstrate the loading state in the widget
      await new Promise((resolve) => setTimeout(resolve, 2000));
      return widget({
        props: { query: query ?? "", results },
        output: text(
          `Found ${results.length} fruits matching "${query ?? "all"}"`,
        ),
      });
    },
  );

  // Companion data tool — called from within the widget via useCallTool("get-fruit-details")
  server.tool(
    {
      name: "get-fruit-details",
      description: "Get detailed information about a specific fruit",
      schema: z.object({
        fruit: z.string().describe("The fruit name"),
      }),
      outputSchema: z.object({
        fruit: z.string(),
        color: z.string(),
        facts: z.array(z.string()),
      }),
    },
    async ({ fruit }) => {
      const found = fruits.find(
        (f) => f.fruit?.toLowerCase() === fruit?.toLowerCase(),
      );
      return object({
        fruit: found?.fruit ?? fruit,
        color: found?.color ?? "unknown",
        facts: [
          `${fruit} is a delicious fruit`,
          `Color: ${found?.color ?? "unknown"}`,
        ],
      });
    },
  );
}

# Example: Three.js App

![Screenshot](screenshot.png)

Interactive 3D scene renderer using Three.js. Demonstrates streaming code preview and full MCP App integration.

## Features

- **Interactive 3D Rendering**: Execute JavaScript code to create and animate Three.js scenes
- **Streaming Preview**: See the scene build in real-time as code is being written
- **Built-in Helpers**: Pre-configured `OrbitControls`, post-processing effects (bloom), and render passes
- **Documentation Tool**: `learn_threejs` provides API docs and code examples on demand

## Running

1. Install dependencies:

   ```bash
   npm install
   ```

2. Build and start the server:

   ```bash
   npm run start:http  # for Streamable HTTP transport
   # OR
   npm run start:stdio  # for stdio transport
   ```

3. View using the [`basic-host`](https://github.com/modelcontextprotocol/ext-apps/tree/main/examples/basic-host) example or another MCP Apps-compatible host.

### Tool Input

To test the example, copy the contents of [`test-input.json`](test-input.json) into the tool input field in `basic-host`.

The test input creates a simple scene with a rotating cube:

```javascript
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(60, width / height, 0.1, 100);
camera.position.set(2, 2, 2);

const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
renderer.setSize(width, height);
renderer.shadowMap.enabled = true;

const cube = new THREE.Mesh(
  new THREE.BoxGeometry(),
  new THREE.MeshStandardMaterial({ color: 0x00ff88 }),
);
cube.castShadow = true;
cube.position.y = 0.5;
scene.add(cube);

const floor = new THREE.Mesh(
  new THREE.PlaneGeometry(5, 5),
  new THREE.MeshStandardMaterial({ color: 0x222233 }),
);
floor.rotation.x = -Math.PI / 2;
floor.receiveShadow = true;
scene.add(floor);

const light = new THREE.DirectionalLight(0xffffff, 2);
light.position.set(3, 5, 3);
light.castShadow = true;
scene.add(light);
scene.add(new THREE.AmbientLight(0x404040));

function animate() {
  requestAnimationFrame(animate);
  cube.rotation.y += 0.01;
  renderer.render(scene, camera);
}
animate();
```

#### Available Three.js Globals

When writing custom code, these globals are available:

```javascript
THREE; // Three.js library
canvas; // Pre-created canvas element
width; // Canvas width
height; // Canvas height
OrbitControls; // Camera controls
EffectComposer; // Post-processing composer
RenderPass; // Render pass
UnrealBloomPass; // Bloom effect
```

## Architecture

### Server (`server.ts`)

Exposes two tools:

- `show_threejs_scene` - Renders a 3D scene from JavaScript code
- `learn_threejs` - Returns documentation and code examples for Three.js APIs

Supports Streamable HTTP and stdio transports.

### App (`src/threejs-app.tsx`)

React component that:

- Receives tool inputs via the MCP App SDK
- Displays streaming preview from `toolInputsPartial.code` as code arrives
- Executes final code from `toolInputs.code` when complete
- Renders to a pre-created canvas with configurable height

/**
 * Shared utilities for running MCP servers with Streamable HTTP transport.
 */

import { createMcpExpressApp } from "@modelcontextprotocol/sdk/server/express.js";
import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";
import cors from "cors";
import type { Request, Response } from "express";

export interface ServerOptions {
  port: number;
  name?: string;
}

/**
 * Starts an MCP server with Streamable HTTP transport in stateless mode.
 *
 * @param createServer - Factory function that creates a new McpServer instance per request.
 * @param options - Server configuration options.
 */
export async function startServer(
  createServer: () => McpServer,
  options: ServerOptions,
): Promise<void> {
  const { port, name = "MCP Server" } = options;

  const app = createMcpExpressApp({ host: "0.0.0.0" });
  app.use(cors());

  app.all("/mcp", async (req: Request, res: Response) => {
    const server = createServer();
    const transport = new StreamableHTTPServerTransport({
      sessionIdGenerator: undefined,
    });

    res.on("close", () => {
      transport.close().catch(() => {});
      server.close().catch(() => {});
    });

    try {
      await server.connect(transport);
      await transport.handleRequest(req, res, req.body);
    } catch (error) {
      console.error("MCP error:", error);
      if (!res.headersSent) {
        res.status(500).json({
          jsonrpc: "2.0",
          error: { code: -32603, message: "Internal server error" },
          id: null,
        });
      }
    }
  });

  const httpServer = app.listen(port, (err) => {
    if (err) {
      console.error("Failed to start server:", err);
      process.exit(1);
    }
    console.log(`${name} listening on http://localhost:${port}/mcp`);
  });

  const shutdown = () => {
    console.log("\nShutting down...");
    httpServer.close(() => process.exit(0));
  };

  process.on("SIGINT", shutdown);
  process.on("SIGTERM", shutdown);
}

