const openai = createOpenAI({
  apiKey: process.env.OPENAI_API_KEY,
});

/** OpenAI chat model for the Mastra agent (`@ai-sdk/openai` id), e.g. gpt-5.5. */
const OPENAI_MODEL = process.env.OPENAI_MODEL?.trim() || "gpt-5.5";

// ── Request handler ──────────────────────────────────────────────────────────
// Architecture:
// - Mastra Agent executes MCP tools directly (via MCPClient — the LLM can see them)
// - A function middleware on the AG-UI Observable layer:
//   (a) Handles proxied MCP requests (MCPAppsActivityRenderer fetching widget HTML)
//   (b) Intercepts TOOL_CALL_RESULT for MCP UI tools → emits ACTIVITY_SNAPSHOT
// - CopilotKit v2's built-in MCPAppsActivityRenderer renders widget iframes

export const POST = async (req: NextRequest) => {
  const requestId = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  let mcp: MCPClient | null = null;

  try {
    const mcpServers = readMcpServersFromHeader(req);
    mastraLog(
      "[mastra-agent] === NEW REQUEST ===",
      requestId,
      "model:",
      OPENAI_MODEL,
    );

    // 1. Fetch UI tool metadata (which tools have UI + their resource URIs)
    const uiTools = await fetchUIToolMetadata(mcpServers);

    // 2. Create Mastra MCP client for tool execution
    const mcpServerConfig: Record<string, { url: URL }> = {};
    for (const server of mcpServers) {
      const serverId = server.serverId || new URL(server.url).hostname;
      mcpServerConfig[serverId] = { url: new URL(server.url) };
    }

    mcp = new MCPClient({
      id: `mastra-agent-${requestId}`,
      servers: mcpServerConfig,
    });

    let mcpTools = {};
    try {
      mcpTools = await mcp.listTools();
      mastraLog("[mastra-agent] MCP tools loaded:", Object.keys(mcpTools));
    } catch (error) {
      console.error("[mastra-agent] Failed to load MCP tools:", error);
    }

    // 3. Create Mastra agent with MCP tools + workspace tools
    const mastraAgent = new Agent({
      id: "default",
      name: "MCP UI Builder",
      instructions: {
        role: "system",
        content: AGENT_SYSTEM_PROMPT,
        providerOptions: {
          openai: {
            reasoningEffort: "minimal", // Options: "minimal", "low", "medium", "high"
          },
        },
      },
      model: openai(OPENAI_MODEL),
      tools: {
        ...mcpTools,
        ...workspaceTools,
      } as Record<string, never>,
      defaultOptions: {
        maxSteps: 25, // Allow up to 25 tool call steps (default is 10)
      },
    });

    // 4. Wrap in AG-UI adapter
    const agentWrapper = new MastraAgent({
      agent: mastraAgent,
      resourceId: "anonymous",
    });

    // 5. Attach AG-UI middleware for ACTIVITY_SNAPSHOT + proxied requests
    //    This operates at the Observable layer (not SSE), so events flow
    //    through CopilotKit v2's pipeline and trigger MCPAppsActivityRenderer.
    // @ts-expect-error - rxjs version mismatch (7.8.1 vs 7.8.2) between @ag-ui packages
    agentWrapper.use(createMcpUIMiddleware(mcpServers, uiTools));

    // FIX: CopilotKit runtime calls `registeredAgent.clone()` before runAgent().
    // MastraAgent.clone() does `new MastraAgent(this.config)` which drops middlewares
    // added via .use(). Override clone() to re-attach our middleware on the clone.
    const mcpMiddleware = createMcpUIMiddleware(mcpServers, uiTools);
    const origClone = agentWrapper.clone.bind(agentWrapper);
    agentWrapper.clone = function () {
      const cloned = origClone();
      // @ts-expect-error - rxjs version mismatch
      cloned.use(mcpMiddleware);
      return cloned;
    };

    mastraLog(
      "[mastra-agent] Agent ready. UI tools:",
      uiTools.size,
      "MCP tools:",
      Object.keys(mcpTools).length,
    );

    // 6. CopilotKit runtime
    const serviceAdapter = new ExperimentalEmptyAdapter();

    const runtime = new CopilotRuntime({
      agents: {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        default: agentWrapper as any,
      },
    });

    const { handleRequest } = copilotRuntimeNextJSAppRouterEndpoint({
      runtime,
      serviceAdapter,
      endpoint: "/api/mastra-agent",
    });

    return handleRequest(req);
  } catch (error) {
    console.error("[mastra-agent] Error:", error);
    return new Response(
      JSON.stringify({
        error: error instanceof Error ? error.message : "Internal server error",
      }),
      {
        status: 500,
        headers: { "Content-Type": "application/json" },
      },
    );
  } finally {
    if (mcp) {
      try {
        await mcp.disconnect();
      } catch {
        /* ignore */
      }
    }
  }
};

import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";
import { SSEClientTransport } from "@modelcontextprotocol/sdk/client/sse.js";
import { NextRequest, NextResponse } from "next/server";

/** Listing tools + fetching widget HTML can be slow; allow up to 5 min. */
export const maxDuration = 300;

/** Shape returned for each discovered tool. */
export interface IntrospectedTool {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
  hasUI: boolean;
  uiResourceUri: string | null;
  uiHtml: string | null;
  uiPreviewData: Record<string, unknown> | null;
  _meta: Record<string, unknown> | null;
}

async function connectClient(url: string) {
  console.log(`[mcp-introspect] Connecting to ${url}...`);

  // Try Streamable HTTP first, fall back to SSE
  try {
    const client = new Client(
      { name: "mcp-studio-introspect", version: "1.0.0" },
      { capabilities: {} },
    );
    const transport = new StreamableHTTPClientTransport(new URL(url));
    await client.connect(transport);
    console.log(`[mcp-introspect] Connected via StreamableHTTP to ${url}`);
    return client;
  } catch (err) {
    console.log(
      `[mcp-introspect] StreamableHTTP failed for ${url}:`,
      (err as Error).message,
    );
    try {
      const client = new Client(
        { name: "mcp-studio-introspect", version: "1.0.0" },
        { capabilities: {} },
      );
      const transport = new SSEClientTransport(new URL(url));
      await client.connect(transport);
      console.log(`[mcp-introspect] Connected via SSE to ${url}`);
      return client;
    } catch (sseErr) {
      console.error(
        `[mcp-introspect] SSE also failed for ${url}:`,
        (sseErr as Error).message,
      );
      throw sseErr;
    }
  }
}

export async function POST(req: NextRequest) {
  let body: { endpoint: string };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const { endpoint } = body;
  if (!endpoint) {
    return NextResponse.json(
      { error: "Missing `endpoint` field" },
      { status: 400 },
    );
  }

  console.log(`[mcp-introspect] POST received for endpoint: ${endpoint}`);
  let client: Client | null = null;
  try {
    client = await connectClient(endpoint);

    // 1. List all tools
    console.log(`[mcp-introspect] Calling listTools()...`);
    const allTools: IntrospectedTool[] = [];
    let cursor: string | undefined;
    do {
      const res = await client.listTools(cursor ? { cursor } : undefined);
      console.log(
        `[mcp-introspect] listTools returned ${res.tools.length} tools`,
      );
      for (const t of res.tools) {
        const meta = (t as Record<string, unknown>)._meta as
          | Record<string, unknown>
          | undefined;
        const uiResourceUri = (meta?.["ui/resourceUri"] as string) ?? null;
        const uiPreviewData =
          (meta?.["ui/previewData"] as Record<string, unknown>) ?? null;
        allTools.push({
          name: t.name,
          description: t.description ?? "",
          inputSchema: t.inputSchema as Record<string, unknown>,
          hasUI: uiResourceUri !== null,
          uiResourceUri,
          uiHtml: null, // populated below
          uiPreviewData,
          _meta: meta ?? null,
        });
      }
      cursor = res.nextCursor;
    } while (cursor);

    console.log(
      `[mcp-introspect] Discovered tools:`,
      allTools.map(
        (t) =>
          `${t.name} (UI: ${t.hasUI}, previewData: ${t.uiPreviewData !== null})`,
      ),
    );

    // 2. For tools with UI, fetch the resource HTML
    for (const tool of allTools) {
      if (tool.uiResourceUri) {
        console.log(
          `[mcp-introspect] Reading resource for ${tool.name}: ${tool.uiResourceUri}`,
        );
        try {
          const res = await client.readResource({
            uri: tool.uiResourceUri,
          });
          const textContent = res.contents.find(
            (c) => typeof (c as Record<string, unknown>).text === "string",
          );
          if (textContent) {
            let html = (textContent as Record<string, unknown>).text as string;
            // Fix widget HTML for CSP-safe rendering in sandboxed iframes:
            // 1. Extract internal origin from <base> tag (e.g. http://localhost:3109)
            // 2. Strip <base> tag — blocked by CSP base-uri 'self' and unnecessary
            //    when JS/CSS are inlined (--inline build) and images use __mcpPublicUrl
            // 3. Rewrite remaining internal origin refs to the external endpoint origin
            //    (for window.__mcpPublicUrl, window.__getFile, etc.)
            const serverOrigin = new URL(endpoint).origin;
            const baseTagMatch = html.match(/<base\s+href="([^"]*)"[^>]*>/i);
            if (baseTagMatch) {
              try {
                const internalOrigin = new URL(baseTagMatch[1]).origin;
                // Strip <base> tag (violates CSP base-uri 'self')
                html = html.replace(/<base\b[^>]*>/gi, "");
                // Rewrite all remaining internal origin references
                if (internalOrigin !== serverOrigin) {
                  html = html.replaceAll(internalOrigin, serverOrigin);
                }
              } catch {
                /* ignore malformed base href */
              }
            }
            tool.uiHtml = html;
            console.log(
              `[mcp-introspect] UI HTML for ${tool.name} (${tool.uiHtml.length} chars)`,
            );
          } else {
            console.log(
              `[mcp-introspect] No text content found in resource for ${tool.name}. Contents:`,
              JSON.stringify(res.contents).slice(0, 300),
            );
          }
        } catch (e) {
          console.warn(`Failed to read resource ${tool.uiResourceUri}:`, e);
        }
      }
    }

    // 3. Also list raw resources
    const allResources: Array<{
      uri: string;
      name: string;
      mimeType?: string;
    }> = [];
    let rCursor: string | undefined;
    do {
      const res = await client.listResources(
        rCursor ? { cursor: rCursor } : undefined,
      );
      for (const r of res.resources) {
        allResources.push({
          uri: r.uri,
          name: r.name ?? r.uri,
          mimeType: r.mimeType,
        });
      }
      rCursor = res.nextCursor;
    } while (rCursor);

    await client.close();

    console.log(
      `[mcp-introspect] Done. ${allTools.length} tools, ${allResources.length} resources`,
    );
    return NextResponse.json({ tools: allTools, resources: allResources });
  } catch (err) {
    console.error(`[mcp-introspect] Error for ${endpoint}:`, err);
    try {
      await client?.close();
    } catch {
      /* ignore */
    }
    const message = err instanceof Error ? err.message : String(err);
    return NextResponse.json({ error: message }, { status: 502 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { Readable } from "stream";
import { getProvider } from "@/lib/workspace";
import {
  getBaseKitPath,
  mergeE2bWorkspaceIntoBaseKit,
} from "@/lib/workspace/merge-download-kit";

/** E2B archive + signed URL can be slow; allow up to 5 min. */
export const maxDuration = 300;

type DownloadBody = {
  workspaceId?: string;
  /** When true, response is the .tar.gz bytes with Content-Disposition (no pop-up on client). */
  stream?: boolean;
  /**
   * When true (default), merge E2B `workspace/` into prebuilt `mcp-apps-starter` if
   * `.download-kit/base.tar.gz` exists (from `prebuild`). Set false for MCP-only tarball.
   */
  fullKit?: boolean;
};

export async function POST(req: NextRequest) {
  try {
    const body = (await req.json()) as DownloadBody;
    const { workspaceId, stream, fullKit = true } = body;
    if (!workspaceId) {
      return NextResponse.json(
        { error: "workspaceId is required" },
        { status: 400 },
      );
    }

    const provider = getProvider();
    const { downloadUrl } = await provider.prepareDownload(workspaceId);

    if (!stream) {
      return NextResponse.json({ downloadUrl });
    }

    const upstream = await fetch(downloadUrl, { redirect: "follow" });
    if (!upstream.ok) {
      const snippet = (await upstream.text().catch(() => "")).slice(0, 200);
      console.error(
        "[workspace/download] upstream fetch failed",
        upstream.status,
        snippet,
      );
      return NextResponse.json(
        { error: `Failed to fetch archive from storage (${upstream.status})` },
        { status: 502 },
      );
    }

    const safeId =
      workspaceId.replace(/[^\w-]/g, "").slice(0, 16) || "workspace";
    const basePath = getBaseKitPath();
    const archive = Buffer.from(await upstream.arrayBuffer());

    if (fullKit && basePath) {
      try {
        const nodeStream = await mergeE2bWorkspaceIntoBaseKit(
          archive,
          basePath,
        );
        const webStream = Readable.toWeb(nodeStream);
        return new NextResponse(webStream as unknown as BodyInit, {
          status: 200,
          headers: {
            "Content-Type": "application/gzip",
            "Content-Disposition": `attachment; filename="mcp-app-kit-${safeId}.tar.gz"`,
          },
        });
      } catch (mergeErr) {
        const msg =
          mergeErr instanceof Error ? mergeErr.message : String(mergeErr);
        console.error(
          "[workspace/download] full-kit merge failed, falling back to MCP-only",
          msg,
        );
      }
    } else if (fullKit && !basePath) {
      console.warn(
        "[workspace/download] fullKit requested but .download-kit/base.tar.gz missing — MCP-only",
      );
    }

    return new NextResponse(archive, {
      status: 200,
      headers: {
        "Content-Type": "application/gzip",
        "Content-Disposition": `attachment; filename="workspace-${safeId}.tar.gz"`,
      },
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    console.error("[workspace/download]", message);
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

