"use client";

import { useState, useCallback, useEffect } from "react";

const noop = () => {};

/**
 * Persist state in localStorage with JSON serialization.
 * SSR-safe: returns initial value until mounted.
 * Use this only for persistence (page reload). For shared state between
 * components, use React Context instead.
 */
export function useLocalStorage<T>(
  key: string,
  initialValue: T,
): [T, (value: T | ((prev: T) => T)) => void] {
  const [stored, setStored] = useState<T>(initialValue);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    if (!mounted || typeof window === "undefined") return;
    try {
      const raw = window.localStorage.getItem(key);
      if (raw != null) {
        setStored(JSON.parse(raw) as T);
      }
    } catch {
      noop();
    }
  }, [key, mounted]);

  const setValue = useCallback(
    (value: T | ((prev: T) => T)) => {
      setStored((prev: T) => {
        const next =
          typeof value === "function" ? (value as (p: T) => T)(prev) : value;
        if (typeof window !== "undefined") {
          try {
            window.localStorage.setItem(key, JSON.stringify(next));
          } catch {
            noop();
          }
        }
        return next;
      });
    },
    [key],
  );

  return [stored, setValue];
}

"use client";

import { useState, useEffect, useCallback, useRef, useMemo } from "react";

/** Mirrors the shape returned by /api/mcp-introspect */
export interface IntrospectedTool {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
  hasUI: boolean;
  uiResourceUri: string | null;
  uiHtml: string | null;
  uiPreviewData: Record<string, unknown> | null;
  _meta: Record<string, unknown> | null;
}

export interface McpResource {
  uri: string;
  name: string;
  mimeType?: string;
}

export interface ServerIntrospection {
  endpoint: string;
  serverId?: string;
  tools: IntrospectedTool[];
  resources: McpResource[];
  error: string | null;
  loading: boolean;
}

/**
 * Fetches tool & resource data from all connected MCP servers via the
 * `/api/mcp-introspect` proxy route.
 *
 * Re-fetches automatically whenever `servers` changes.
 */
export function useMcpIntrospect(
  servers: { endpoint: string; serverId?: string }[],
) {
  const [data, setData] = useState<ServerIntrospection[]>([]);
  const [loading, setLoading] = useState(false);
  const abortRef = useRef<AbortController | null>(null);

  const refresh = useCallback(async () => {
    // Abort any in-flight requests
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;

    if (servers.length === 0) {
      console.log("[useMcpIntrospect] No servers configured, skipping");
      setData([]);
      setLoading(false);
      return;
    }

    console.log(
      "[useMcpIntrospect] Fetching from",
      servers.length,
      "server(s):",
      servers.map((s) => s.endpoint),
    );
    setLoading(true);

    const results = await Promise.all(
      servers.map(async (server) => {
        const entry: ServerIntrospection = {
          endpoint: server.endpoint,
          serverId: server.serverId,
          tools: [],
          resources: [],
          error: null,
          loading: true,
        };

        try {
          console.log(`[useMcpIntrospect] Fetching ${server.endpoint}...`);
          const res = await fetch("/api/mcp-introspect", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ endpoint: server.endpoint }),
            signal: controller.signal,
          });

          console.log(
            `[useMcpIntrospect] Response from ${server.endpoint}: ${res.status}`,
          );

          if (!res.ok) {
            const body = await res.json().catch(() => ({}));
            entry.error =
              (body as Record<string, string>).error ?? `HTTP ${res.status}`;
            console.error(
              `[useMcpIntrospect] Error for ${server.endpoint}:`,
              entry.error,
            );
          } else {
            const body = await res.json();
            entry.tools = body.tools ?? [];
            entry.resources = body.resources ?? [];
            console.log(
              `[useMcpIntrospect] Got ${entry.tools.length} tools, ${entry.resources.length} resources from ${server.endpoint}`,
            );
          }
        } catch (err) {
          if ((err as Error).name !== "AbortError") {
            entry.error = (err as Error).message ?? String(err);
            console.error(
              `[useMcpIntrospect] Fetch failed for ${server.endpoint}:`,
              entry.error,
            );
          }
        }

        entry.loading = false;
        return entry;
      }),
    );

    if (!controller.signal.aborted) {
      setData(results);
      setLoading(false);
    }
  }, [servers]);

  // Auto-fetch on server list change
  useEffect(() => {
    refresh();
    return () => abortRef.current?.abort();
  }, [refresh]);

  // Stable reference — flatMap always creates a new array, so memoize by
  // serializing tool names to avoid triggering downstream useEffects on every render.
  const allTools = useMemo(
    () => data.flatMap((s) => s.tools),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [data],
  );

  return { data, allTools, loading, refresh };
}

"use client";

import { useCallback, useEffect, useMemo } from "react";
import { useLocalStorage } from "./useLocalStorage";
import type { IntrospectedTool } from "./useMcpIntrospect";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/** Locally stored tool configuration — supports overrides and brand-new tools */
export interface LocalToolConfig {
  toolName: string;
  source: "introspected" | "local";
  description: string;
  inputSchema: Record<string, unknown>;
  htmlSource: string | null;
  previewData: Record<string, unknown>;
  serverEndpoint?: string;
  createdAt: number;
  updatedAt: number;
}

/** Merged view shown in the UI: introspected data + local overrides */
export interface MergedToolConfig {
  toolName: string;
  source: "introspected" | "local";
  description: string;
  inputSchema: Record<string, unknown>;
  htmlSource: string | null;
  previewData: Record<string, unknown>;
  hasUI: boolean;
  uiResourceUri: string | null;
  _meta: Record<string, unknown> | null;
  isModified: boolean;
}

// ---------------------------------------------------------------------------
// Mock data generator
// ---------------------------------------------------------------------------

export function generatePreviewData(
  inputSchema: Record<string, unknown>,
): Record<string, unknown> {
  const props = inputSchema?.properties as
    | Record<
        string,
        {
          type?: string;
          description?: string;
          enum?: string[];
          default?: unknown;
        }
      >
    | undefined;
  if (!props) return {};
  const mock: Record<string, unknown> = {};
  for (const [key, schema] of Object.entries(props)) {
    if (schema.default !== undefined) {
      mock[key] = schema.default;
    } else if (schema.enum && schema.enum.length > 0) {
      mock[key] = schema.enum[0];
    } else {
      switch (schema.type) {
        case "string":
          mock[key] = schema.description
            ? schema.description.slice(0, 80)
            : `sample_${key}`;
          break;
        case "number":
        case "integer":
          mock[key] = 42;
          break;
        case "boolean":
          mock[key] = true;
          break;
        case "array":
          mock[key] = [];
          break;
        case "object":
          mock[key] = {};
          break;
        default:
          mock[key] = `sample_${key}`;
      }
    }
  }
  return mock;
}

// ---------------------------------------------------------------------------
// Validation helpers
// ---------------------------------------------------------------------------

export interface ValidationResult {
  test: string;
  passed: boolean;
  message: string;
}

export function validateToolConfig(config: MergedToolConfig): {
  summary: string;
  results: ValidationResult[];
  allPassed: boolean;
} {
  const results: ValidationResult[] = [];

  // 1. Schema structure
  const schema = config.inputSchema;
  if (!schema || typeof schema !== "object") {
    results.push({
      test: "Schema structure",
      passed: false,
      message: "Schema is not a valid object",
    });
  } else if (
    !(schema as Record<string, unknown>).properties &&
    !(schema as Record<string, unknown>).type
  ) {
    results.push({
      test: "Schema structure",
      passed: false,
      message: "Schema missing 'type' or 'properties'",
    });
  } else {
    results.push({
      test: "Schema structure",
      passed: true,
      message: "Valid JSON Schema structure",
    });
  }

  // 2. Mock data completeness
  const required =
    ((schema as Record<string, unknown>)?.required as string[]) ?? [];
  const mockKeys = Object.keys(config.previewData);
  const missingRequired = required.filter((r) => !mockKeys.includes(r));
  if (missingRequired.length > 0) {
    results.push({
      test: "Mock data completeness",
      passed: false,
      message: `Missing required fields: ${missingRequired.join(", ")}`,
    });
  } else {
    results.push({
      test: "Mock data completeness",
      passed: true,
      message: `All ${required.length} required fields present`,
    });
  }

  // 3. Mock data type matching
  const props =
    ((schema as Record<string, unknown>)?.properties as Record<
      string,
      { type?: string }
    >) ?? {};
  let typeErrors = 0;
  for (const [key, value] of Object.entries(config.previewData)) {
    const propSchema = props[key];
    if (propSchema?.type) {
      const actualType = Array.isArray(value) ? "array" : typeof value;
      const expectedType =
        propSchema.type === "integer" ? "number" : propSchema.type;
      if (actualType !== expectedType) {
        typeErrors++;
      }
    }
  }
  results.push({
    test: "Mock data types",
    passed: typeErrors === 0,
    message:
      typeErrors === 0
        ? "All types match schema"
        : `${typeErrors} type mismatch(es)`,
  });

  // 4. HTML check
  if (config.hasUI || config.htmlSource) {
    if (!config.htmlSource || config.htmlSource.length === 0) {
      results.push({
        test: "UI HTML",
        passed: false,
        message: "HTML source is empty",
      });
    } else if (!config.htmlSource.includes("<script")) {
      results.push({
        test: "UI HTML",
        passed: false,
        message: "HTML has no <script> tags",
      });
    } else {
      results.push({
        test: "UI HTML",
        passed: true,
        message: `Valid HTML (${(config.htmlSource.length / 1024).toFixed(1)} KB)`,
      });
    }
  }

  // 5. Description check
  if (!config.description || config.description.length < 5) {
    results.push({
      test: "Description",
      passed: false,
      message: "Description is too short or missing",
    });
  } else {
    results.push({
      test: "Description",
      passed: true,
      message: "Description looks good",
    });
  }

  const passed = results.filter((r) => r.passed).length;
  return {
    summary: `${passed}/${results.length} checks passed`,
    results,
    allPassed: passed === results.length,
  };
}

