/**
 * Server-side default MCP servers when no x-mcp-servers header is present.
 * Unset = no defaults. Set DEFAULT_MCP_SERVERS (JSON array) to pre-fill.
 */

export type McpServerConfig = {
  type: "http" | "sse";
  url: string;
  serverId?: string;
};

/** Built-in default: Excalidraw MCP server (public, no auth). Override with DEFAULT_MCP_SERVERS env. */
const BUILTIN_DEFAULTS: McpServerConfig[] = [
  { type: "http", url: "https://mcp.excalidraw.com", serverId: "excalidraw" },
];

function parseDefaultMcpServers(): McpServerConfig[] {
  const raw = process.env.DEFAULT_MCP_SERVERS;
  if (raw == null || raw === "") return BUILTIN_DEFAULTS;
  try {
    const parsed = JSON.parse(raw) as McpServerConfig[];
    if (!Array.isArray(parsed)) return BUILTIN_DEFAULTS;
    const filtered = parsed.filter(
      (s): s is McpServerConfig =>
        s != null &&
        typeof s.url === "string" &&
        (s.type === "http" || s.type === "sse"),
    );
    return filtered.length > 0 ? filtered : BUILTIN_DEFAULTS;
  } catch {
    return BUILTIN_DEFAULTS;
  }
}

let cached: McpServerConfig[] | null = null;

/** Default MCP server configs for API routes when header is absent. */
export function getDefaultMcpServers(): McpServerConfig[] {
  if (cached === null) cached = parseDefaultMcpServers();
  return cached;
}

/**
 * Save a Blob as a file using the browser download path (no pop-up).
 * Works after async fetch when the response is same-origin (e.g. /api/workspace/download?stream).
 */
export function triggerBlobDownload(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.rel = "noopener";
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

import { Sandbox } from "e2b";
import type {
  WorkspaceProvider,
  WorkspaceInfo,
  ExecOpts,
  ExecResult,
} from "./types";

const WORKSPACE_PATH = "/home/user/workspace";
// Hardcoded fallback so sandbox clone works without env; override with E2B_REPO_URL if needed
const REPO_URL =
  process.env.E2B_REPO_URL ?? "https://github.com/CopilotKit/CopilotKit";
const TEMPLATE_ID = process.env.E2B_TEMPLATE;
// Default sandbox lifetime: 60 minutes (can be extended during a session)
const SANDBOX_TIMEOUT_MS = 60 * 60 * 1000;

export class E2BWorkspaceProvider implements WorkspaceProvider {
  async provision(_name: string): Promise<WorkspaceInfo> {
    if (!TEMPLATE_ID && !REPO_URL) {
      throw new Error(
        "Set E2B_TEMPLATE (recommended) or E2B_REPO_URL in your .env.local.",
      );
    }

    // Create sandbox — use custom template if provided (pre-installed deps = faster cold start)
    const sandbox = TEMPLATE_ID
      ? await Sandbox.create(TEMPLATE_ID, { timeoutMs: SANDBOX_TIMEOUT_MS })
      : await Sandbox.create({ timeoutMs: SANDBOX_TIMEOUT_MS });

    if (TEMPLATE_ID) {
      // Template has node_modules + dist pre-built, and setStartCmd already
      // started the server on port 3109 when the sandbox booted.
      // Nothing to do — just get the endpoint below.
    } else {
      // No template — full cold start: clone + install (~60-90s)
      const clone = await sandbox.commands.run(
        `git clone --depth 1 ${REPO_URL} ${WORKSPACE_PATH}`,
        { timeoutMs: 2 * 60_000 },
      );
      if (clone.exitCode !== 0) {
        await sandbox.kill();
        throw new Error(
          `git clone failed (exit ${clone.exitCode}): ${clone.stderr}`,
        );
      }

      const install = await sandbox.commands.run(
        `cd ${WORKSPACE_PATH} && npm install --no-audit --no-fund --prefer-offline`,
        { timeoutMs: 15 * 60_000 },
      );
      if (install.exitCode !== 0) {
        await sandbox.kill();
        throw new Error(
          `npm install failed (exit ${install.exitCode}): ${install.stderr}`,
        );
      }

      // Start dev server in background and wait for it to come up
      await sandbox.commands.run(`cd ${WORKSPACE_PATH} && npm run dev`, {
        background: true,
      });
      await new Promise((r) => setTimeout(r, 10_000));
    }

    const endpoint = await this._getMcpEndpoint(sandbox);

    return {
      workspaceId: sandbox.sandboxId,
      endpoint,
      status: "running",
      path: WORKSPACE_PATH,
    };
  }

  async getInfo(workspaceId: string): Promise<WorkspaceInfo> {
    const sandbox = await Sandbox.connect(workspaceId);
    const endpoint = await this._getMcpEndpoint(sandbox);
    return { workspaceId, endpoint, status: "running", path: WORKSPACE_PATH };
  }

  async stop(workspaceId: string): Promise<void> {
    const sandbox = await Sandbox.connect(workspaceId);
    await sandbox.kill();
  }

  async readFile(workspaceId: string, path: string): Promise<string> {
    const sandbox = await Sandbox.connect(workspaceId);
    return sandbox.files.read(this._fullPath(path));
  }

  async writeFile(
    workspaceId: string,
    path: string,
    content: string,
  ): Promise<void> {
    const sandbox = await Sandbox.connect(workspaceId);
    const full = this._fullPath(path);
    // Ensure parent directory exists
    const dir = full.substring(0, full.lastIndexOf("/"));
    await sandbox.commands.run(`mkdir -p "${dir}"`);
    await sandbox.files.write(full, content);
  }

  async editFile(
    workspaceId: string,
    path: string,
    search: string,
    replace: string,
  ): Promise<void> {
    const sandbox = await Sandbox.connect(workspaceId);
    const full = this._fullPath(path);
    const content = await sandbox.files.read(full);
    if (!content.includes(search)) {
      throw new Error(
        `Search string not found in "${path}". Make sure the search string matches exactly.`,
      );
    }
    await sandbox.files.write(full, content.replace(search, replace));
  }

  async exec(
    workspaceId: string,
    cmd: string,
    opts?: ExecOpts,
  ): Promise<ExecResult> {
    const sandbox = await Sandbox.connect(workspaceId);

    if (opts?.background) {
      await sandbox.commands.run(cmd, {
        cwd: opts.cwd ?? WORKSPACE_PATH,
        background: true,
      });
      return { stdout: "", stderr: "", exitCode: 0, background: true };
    }

    const result = await sandbox.commands.run(cmd, {
      cwd: opts?.cwd ?? WORKSPACE_PATH,
      timeoutMs: opts?.timeoutMs ?? 60_000,
    });

    return {
      stdout: result.stdout ?? "",
      stderr: result.stderr ?? "",
      exitCode: result.exitCode ?? 0,
    };
  }

  async prepareDownload(workspaceId: string): Promise<{ downloadUrl: string }> {
    const sandbox = await Sandbox.connect(workspaceId);
    // Strip heavy dirs, then archive with tar (GNU zip is often missing → exit 127 on `zip`).
    const clean = await sandbox.commands.run(
      `cd ${WORKSPACE_PATH} && rm -rf node_modules dist .agent`,
      { timeoutMs: 120_000 },
    );
    if (clean.exitCode !== 0) {
      throw new Error(
        `Failed to prepare workspace for download: ${clean.stderr || clean.stdout || "unknown error"}`,
      );
    }
    const archive = await sandbox.commands.run(
      `cd /home/user && rm -f workspace.tar.gz workspace.zip && tar -czf workspace.tar.gz workspace`,
      { timeoutMs: 5 * 60_000 },
    );
    if (archive.exitCode !== 0) {
      throw new Error(
        `Archive failed (exit ${archive.exitCode}): ${archive.stderr || archive.stdout || "is tar available?"}`,
      );
    }
    const url = await sandbox.downloadUrl("/home/user/workspace.tar.gz");
    return { downloadUrl: url };
  }

  // ── helpers ────────────────────────────────────────────────────────────────

  private async _getMcpEndpoint(sandbox: Sandbox): Promise<string> {
    // Prefer the E2B-managed MCP URL (no port wrangling required).
    // betaGetMcpUrl is a beta method not yet in the public type definitions.
    try {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const url = (sandbox as any).betaGetMcpUrl?.();
      if (url) return url as string;
    } catch {
      // betaGetMcpUrl not available in this SDK version — fall through
    }
    // Fallback: map the default mcp-use port
    return `https://${sandbox.getHost(3109)}/mcp`;
  }

  private _fullPath(relativePath: string): string {
    // Strip leading slash if present, then join
    const clean = relativePath.replace(/^\//, "");
    return `${WORKSPACE_PATH}/${clean}`;
  }
}

import { E2BWorkspaceProvider } from "./e2b";
import type { WorkspaceProvider } from "./types";

let _provider: WorkspaceProvider | null = null;

/** Returns a singleton WorkspaceProvider for the current process. */
export function getProvider(): WorkspaceProvider {
  if (!_provider) {
    _provider = new E2BWorkspaceProvider();
  }
  return _provider;
}

export type {
  WorkspaceProvider,
  WorkspaceInfo,
  ExecOpts,
  ExecResult,
} from "./types";

import { createReadStream, existsSync } from "fs";
import fs from "fs/promises";
import os from "os";
import path from "path";
import type { Readable } from "stream";
import * as tar from "tar";

/** E2B prepareDownload produces a tarball whose top-level directory is `workspace`. */
const E2B_WORKSPACE_DIR = "workspace";
export const KIT_FOLDER_NAME = "mcp-apps-starter";

export function getBaseKitPath(): string | null {
  const p = path.join(process.cwd(), ".download-kit", "base.tar.gz");
  return existsSync(p) ? p : null;
}

/**
 * Unpacks the prebuilt base kit and the E2B workspace archive, replaces
 * `apps/mcp-use-server` with the sandbox tree, and returns a gzip tarball stream.
 * Caller should destroy the stream or wait for `close` so temp dirs can be removed.
 */
export async function mergeE2bWorkspaceIntoBaseKit(
  workspaceTarGz: Buffer,
  baseTarGzPath: string,
): Promise<Readable> {
  const tmp = await fs.mkdtemp(path.join(os.tmpdir(), "mcp-kit-"));
  const workspaceArchive = path.join(tmp, "workspace.tar.gz");
  const baseExtract = path.join(tmp, "base");
  const wsExtract = path.join(tmp, "e2b");

  try {
    await fs.writeFile(workspaceArchive, workspaceTarGz);

    await fs.mkdir(baseExtract, { recursive: true });
    await tar.x({ file: baseTarGzPath, cwd: baseExtract });

    const kitPath = path.join(baseExtract, KIT_FOLDER_NAME);
    const stat = await fs.stat(kitPath).catch(() => null);
    if (!stat?.isDirectory()) {
      throw new Error(`Base kit missing ${KIT_FOLDER_NAME}/ at tarball root`);
    }

    await fs.mkdir(wsExtract, { recursive: true });
    await tar.x({ file: workspaceArchive, cwd: wsExtract });

    const wsPath = path.join(wsExtract, E2B_WORKSPACE_DIR);
    const wsStat = await fs.stat(wsPath).catch(() => null);
    if (!wsStat?.isDirectory()) {
      throw new Error(
        `E2B archive missing ${E2B_WORKSPACE_DIR}/ at tarball root`,
      );
    }

    const mcpDest = path.join(kitPath, "apps", "mcp-use-server");
    await fs.rm(mcpDest, { recursive: true, force: true });
    await fs.rename(wsPath, mcpDest);

    const outFile = path.join(tmp, "merged.tar.gz");
    await tar.c(
      { gzip: true, file: outFile, cwd: baseExtract, portable: true },
      [KIT_FOLDER_NAME],
    );

    const rs = createReadStream(outFile);
    rs.on("close", () => {
      void fs.rm(tmp, { recursive: true, force: true }).catch(() => {});
    });
    rs.on("error", () => {
      void fs.rm(tmp, { recursive: true, force: true }).catch(() => {});
    });

    return rs;
  } catch (e) {
    await fs.rm(tmp, { recursive: true, force: true }).catch(() => {});
    throw e;
  }
}

export interface WorkspaceInfo {
  workspaceId: string; // e2b: sandboxId
  endpoint: string; // MCP URL from sandbox.betaGetMcpUrl()
  status: "provisioning" | "running" | "stopped";
  path: string; // /home/user/workspace inside the sandbox
}

export interface ExecOpts {
  cwd?: string;
  background?: boolean;
  timeoutMs?: number;
}

export interface ExecResult {
  stdout: string;
  stderr: string;
  exitCode: number;
  background?: boolean; // true if the process was started in background (no exit code yet)
}

export interface WorkspaceProvider {
  provision(name: string): Promise<WorkspaceInfo>;
  getInfo(workspaceId: string): Promise<WorkspaceInfo>;
  stop(workspaceId: string): Promise<void>;

  readFile(workspaceId: string, path: string): Promise<string>;
  writeFile(workspaceId: string, path: string, content: string): Promise<void>;
  editFile(
    workspaceId: string,
    path: string,
    search: string,
    replace: string,
  ): Promise<void>;

  exec(workspaceId: string, cmd: string, opts?: ExecOpts): Promise<ExecResult>;
  prepareDownload(workspaceId: string): Promise<{ downloadUrl: string }>;
}

import type { NextConfig } from "next";
import dotenv from "dotenv";

dotenv.config({
  path: "../../.env",
});

const nextConfig: NextConfig = {
  output: "standalone",
  serverExternalPackages: ["@copilotkit/runtime"],
  /** Bundle prebuilt monorepo shell for full-kit workspace download (see prebuild / pack-download-kit). */
  outputFileTracingIncludes: {
    "/api/workspace/download": [".download-kit/base.tar.gz"],
  },
};

export default nextConfig;

const config = {
  plugins: ["@tailwindcss/postcss"],
};

export default config;

/**
 * Builds apps/web/.download-kit/base.tar.gz — monorepo shell (no node_modules / .next / dist)
 * for merging with the E2B workspace on download. Run via prebuild before next build.
 */
import fs from "fs/promises";
import os from "os";
import path from "path";
import { fileURLToPath } from "url";
import { createWriteStream } from "fs";
import { pipeline } from "stream/promises";
import * as tar from "tar";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const WEB_ROOT = path.resolve(__dirname, "..");
const REPO_ROOT = path.resolve(WEB_ROOT, "..", "..");
const OUT_DIR = path.join(WEB_ROOT, ".download-kit");
const OUT_FILE = path.join(OUT_DIR, "base.tar.gz");
const KIT_ROOT = "mcp-apps-starter";

const SKIP_DIR_NAMES = new Set([
  "node_modules",
  ".next",
  ".turbo",
  "dist",
  ".vercel",
  ".git",
  "coverage",
  ".agent",
  ".download-kit",
]);

function shouldSkipDir(name) {
  return SKIP_DIR_NAMES.has(name);
}

const KIT_README = `# ${KIT_ROOT}

This archive was produced by **MCP App builder** (download with **full app kit**). It matches this starter layout: root workspace, \`apps/web\`, \`apps/mcp-use-server\` (your sandbox code), and \`apps/threejs-server\`.

## Setup

1. Copy environment: \`cp .env.example .env\` (PowerShell: \`Copy-Item .env.example .env\`) and set \`OPENAI_API_KEY\` and any E2B vars you need.
2. Install: \`pnpm i\`
3. Run everything from the repo root: \`pnpm dev\` (Turbo starts web + configured apps — see root \`package.json\` / \`turbo.json\`).

Your downloaded MCP server lives in \`apps/mcp-use-server\`. See root \`README.md\` and \`docs/DEPLOY.md\` for deployment notes.

`;

async function pathExists(p) {
  try {
    await fs.access(p);
    return true;
  } catch {
    return false;
  }
}

async function copyFiltered(src, dest) {
  const stat = await fs.stat(src);
  if (stat.isDirectory()) {
    const base = path.basename(src);
    if (shouldSkipDir(base)) return;
    await fs.mkdir(dest, { recursive: true });
    const entries = await fs.readdir(src, { withFileTypes: true });
    for (const e of entries) {
      if (shouldSkipDir(e.name)) continue;
      await copyFiltered(path.join(src, e.name), path.join(dest, e.name));
    }
  } else {
    await fs.copyFile(src, dest);
  }
}

async function main() {
  const tmp = await fs.mkdtemp(path.join(os.tmpdir(), "pack-kit-"));
  const stage = path.join(tmp, KIT_ROOT);
  try {
    await fs.mkdir(stage, { recursive: true });
    await fs.writeFile(path.join(stage, "README.md"), KIT_README, "utf8");

    const rootFiles = [
      "package.json",
      "pnpm-workspace.yaml",
      "turbo.json",
      ".env.example",
    ];
    for (const f of rootFiles) {
      const from = path.join(REPO_ROOT, f);
      if (await pathExists(from)) {
        await fs.copyFile(from, path.join(stage, f));
      }
    }

    const appsSrc = path.join(REPO_ROOT, "apps");
    if (!(await pathExists(appsSrc))) {
      throw new Error(`Expected ${appsSrc} — run from monorepo with apps/web`);
    }
    const appsDest = path.join(stage, "apps");
    await fs.mkdir(appsDest, { recursive: true });
    const appDirs = await fs.readdir(appsSrc, { withFileTypes: true });
    for (const d of appDirs) {
      if (!d.isDirectory()) continue;
      await copyFiltered(
        path.join(appsSrc, d.name),
        path.join(appsDest, d.name),
      );
    }

    await fs.mkdir(OUT_DIR, { recursive: true });
    const ws = createWriteStream(OUT_FILE);
    await pipeline(
      tar.c({ gzip: true, cwd: tmp, portable: true }, [KIT_ROOT]),
      ws,
    );
    const st = await fs.stat(OUT_FILE);
    console.log(
      `[pack-download-kit] wrote ${OUT_FILE} (${(st.size / 1024 / 1024).toFixed(2)} MiB)`,
    );
  } finally {
    await fs.rm(tmp, { recursive: true, force: true });
  }
}

main().catch((err) => {
  console.error("[pack-download-kit]", err);
  process.exit(1);
});

